/** Removes every comment document belonging to one issue. */
export async function deleteCommentDocumentsForIssue(
  orgId: OrgId,
  issueId: string,
): Promise<void> {
  getDb().run(sql`DELETE FROM search_index
    WHERE org_id = ${orgId} AND subject_kind = 'comment'
      AND subject_id IN (SELECT id FROM comments WHERE org_id = ${orgId} AND issue_id = ${issueId})`);
}

/** Removes the issue and comment documents of every issue in a project. */
export async function deleteDocumentsForProject(
  orgId: OrgId,
  projectId: string,
): Promise<void> {
  const db = getDb();
  db.run(sql`DELETE FROM search_index
    WHERE org_id = ${orgId} AND subject_kind = 'comment'
      AND subject_id IN (
        SELECT c.id FROM comments c JOIN issues i ON i.id = c.issue_id AND i.org_id = c.org_id
        WHERE c.org_id = ${orgId} AND i.project_id = ${projectId})`);
  db.run(sql`DELETE FROM search_index
    WHERE org_id = ${orgId} AND subject_kind = 'issue'
      AND subject_id IN (SELECT id FROM issues WHERE org_id = ${orgId} AND project_id = ${projectId})`);
}

/** Deletes this org's documents that the visibility rule does not allow. */
export async function pruneIneligibleDocuments(orgId: OrgId): Promise<void> {
  getDb().run(sql`DELETE FROM search_index
    WHERE org_id = ${orgId} AND NOT ${eligiblePredicate()}`);
}

